parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "classifications": {
      "type": "array",
      "description": "Una clasificación por cada publicación recibida",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "type": "string",
            "description": "Identificador original de la publicación"
          },
          "sentiment": {
            "type": "string",
            "enum": ["POS", "NEG", "NEU"],
            "description": "Sentimiento de la publicación"
          }
        },
        "required": ["id", "sentiment"],
        "additionalProperties": false
      }
    }
  },
  "required": ["classifications"],
  "additionalProperties": false
}

parameters.jsCode:
const originalItems = Object.values($('Scrapper').first().json.items ?? {});
const originalById = new Map(
  originalItems.map((item) => [String(item.id), item]),
);

const classifications = $json.output?.classifications;
if (!Array.isArray(classifications)) {
  throw new Error('La respuesta del LLM no contiene classifications');
}

if (classifications.length !== originalItems.length) {
  throw new Error(
    `Se recibieron ${classifications.length} clasificaciones para ${originalItems.length} publicaciones`,
  );
}

const allowedSentiments = new Set(['POS', 'NEG', 'NEU']);
const seenIds = new Set();
const classifiedAt = new Date().toISOString();

return classifications.map((classification) => {
  const id = String(classification.id);
  const sentiment = classification.sentiment;

  if (!allowedSentiments.has(sentiment)) {
    throw new Error(`Sentimiento inválido para ${id}: ${sentiment}`);
  }
  if (seenIds.has(id)) {
    throw new Error(`El LLM devolvió un id duplicado: ${id}`);
  }

  const original = originalById.get(id);
  if (!original) {
    throw new Error(`El LLM devolvió un id desconocido: ${id}`);
  }

  seenIds.add(id);
  return {
    json: {
      ...original,
      sentiment_llm: sentiment,
      llm_model: 'gpt-5-mini',
      llm_prompt_version: '2',
      llm_classified_at: classifiedAt,
    },
  };
});
